import { esc, money } from '../ui.js';
export const docTotal = doc => doc.rows.reduce((sum,r)=>sum+Number(r.quantity||0)*Number(r.price||0),0)*(1-Number(doc.discount||0)/100);
export default function documentPage({ui}) {
 const doc=ui.document;
 return `<form class="card" data-form="document"><div class="toolbar"><label class="field grow"><span>שם המסמך</span><input name="title" id="doc-title" data-field="doc-title" value="${esc(doc.title)}" required maxlength="80"></label><button type="button" class="outline" data-action="add-line">הוספת שורה</button></div><div class="table-wrap"><table><thead><tr><th>פריט</th><th>כמות</th><th>מחיר יחידה</th><th>סכום</th><th>פעולות</th></tr></thead><tbody>${doc.rows.map((r,i)=>`<tr><td><input aria-label="פריט ${i+1}" id="line-name-${i}" data-field="doc-row" data-key="name" data-index="${i}" value="${esc(r.name)}" required maxlength="100"></td><td><input aria-label="כמות ${i+1}" id="line-quantity-${i}" data-field="doc-row" data-key="quantity" data-index="${i}" type="number" min="1" max="9999" step="1" value="${r.quantity}" required style="width:90px"></td><td><input aria-label="מחיר ${i+1}" id="line-price-${i}" data-field="doc-row" data-key="price" data-index="${i}" type="number" min="0" max="999999" step="0.01" value="${r.price}" required style="width:110px"></td><td data-line-total="${i}">${money(r.quantity*r.price)}</td><td><button type="button" class="danger small" data-action="remove-line" data-index="${i}" ${doc.rows.length===1?'disabled':''}>הסרה</button></td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:18px"><label class="field"><span>הנחה (%)</span><input id="doc-discount" data-field="doc-discount" type="number" min="0" max="100" step="0.1" value="${doc.discount}" required></label></div><p class="total">סה״כ: <span id="doc-total">${money(docTotal(doc))}</span></p><p class="muted">מסמך הדגמה בלבד. הסכום אינו כולל חישובי מס או כללי חשבונאות.</p><div class="form-actions"><button type="button" class="outline" data-action="cancel-document">ביטול שינויים</button><button>שמירת טיוטה</button></div></form>`;
}
